package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.content.pm.ProviderInfo;import android.graphics.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.concurrent.TimeUnit;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk=33,qualifiers="w720dp-h360dp-land-mdpi",application=Application.class,shadows={PdfLaunchTest.RendererDouble.class,PdfLaunchTest.PageDouble.class})
@LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ReaderLayout5152Test {
 ActivityController<ReaderActivity> controller;ReaderActivity a;
 void open(boolean continuous)throws Exception{Application app=RuntimeEnvironment.getApplication();new ReaderFixes5141Test().assets();app.getSharedPreferences("seeky",0).edit().putString("theme","Claro").putBoolean("reader_continuous",continuous).putInt("reader_fit",1).apply();PdfLaunchTest.PdfProvider provider=new PdfLaunchTest.PdfProvider();ProviderInfo info=new ProviderInfo();info.authority="seeky.layout5152";provider.attachInfo(app,info);ShadowContentResolver.registerProviderInternal(info.authority,provider);controller=Robolectric.buildActivity(ReaderActivity.class,new Intent(app,ReaderActivity.class).setDataAndType(Uri.parse("content://seeky.layout5152/book.pdf"),"application/pdf").putExtra("name","Livro de teste.pdf").putExtra("study_path","Livros"));a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create().start().resume().visible();a.pdfFit=1;layout(720,360);}
 void layout(int w,int h)throws Exception{a.getWindow().setLayout(w,h);for(int n=0;n<5;n++){a.worker.submit(()->{}).get(20,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();a.root.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));a.root.layout(0,0,w,h);shadowOf(Looper.getMainLooper()).idle();}}
 @After public void close(){if(controller!=null)controller.pause().stop().destroy();SpeechEvents.state=new SpeechEvents.State("","","",0,0,0,false,false);}
 void drag(View view,float x,float y,float dx,float dy)throws Exception{long t=SystemClock.uptimeMillis();for(int i=0;i<=6;i++){MotionEvent e=MotionEvent.obtain(t,t+i*30,i==0?MotionEvent.ACTION_DOWN:i==6?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE,x+dx*i/6,y+dy*i/6,0);view.dispatchTouchEvent(e);e.recycle();shadowOf(Looper.getMainLooper()).idleFor(30,TimeUnit.MILLISECONDS);} }
 void capture(String name)throws Exception{Bitmap b=Bitmap.createBitmap(a.root.getWidth(),a.root.getHeight(),Bitmap.Config.ARGB_8888);a.root.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-5152-"+name+".png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void landscapeKeepsMostHeightForPageAndAllToolsReachable()throws Exception{open(false);assertTrue(a.chrome.compact);assertTrue("viewport "+a.body.getHeight(),a.body.getHeight()>=260);assertEquals(44,a.chrome.top.getHeight());assertEquals(44,a.chrome.bottom.getHeight());assertNotNull(PageTurnTest.findDescription(a.root,"Marcadores"));assertNotNull(PageTurnTest.findDescription(a.root,"Notas deste livro"));assertEquals(View.VISIBLE,a.chrome.actions.getVisibility());capture("landscape");assertTrue("each tool remains reachable",a.chrome.toolStrip.getChildAt(8).getRight()<=a.chrome.toolStrip.getWidth());UiSpacing.apply(a.root);layout(720,360);assertTrue(a.body.getHeight()>=260);capture("landscape");}
 @Test public void widthFittedPdfPansBothWaysThroughTheActualList()throws Exception{open(false);ReaderPageView page=(ReaderPageView)a.pageList.getChildAt(0);assertEquals(page.base,page.scale,.01f);assertTrue("fit="+a.pdfFit+" content="+page.imageHeight(page.getDrawable())*page.scale+" viewport="+page.getHeight(),page.imageHeight(page.getDrawable())*page.scale>page.getHeight()*2);float before=page.ty;drag(a.pageList,300,190,0,-110);assertTrue("vertical pan "+before+" -> "+page.ty,page.ty<before-60);assertEquals(0,a.currentPage);float moved=page.ty;drag(a.pageList,300,60,0,100);assertTrue("reverse "+moved+" -> "+page.ty,page.ty>moved+50);capture("pdf-pan");}
 @Test public void landscapePdfHorizontalSwipeStillTurnsPages()throws Exception{open(false);drag(a.pageList,560,100,-190,2);layout(720,360);assertEquals(1,a.currentPage);drag(a.pageList,250,100,190,2);layout(720,360);assertEquals(0,a.currentPage);}
 @Test public void continuousPdfLeavesVerticalScrollToTheList()throws Exception{open(true);int before=a.pageList.getChildAt(0).getTop();drag(a.pageList,300,190,0,-110);assertTrue(a.pageList.getFirstVisiblePosition()>0||a.pageList.getChildAt(0).getTop()<before-40);assertEquals(1f,((ReaderPageView)a.pageList.getChildAt(0)).scale/((ReaderPageView)a.pageList.getChildAt(0)).base,.01f);}
 @Test public void zoomedPdfPansWithoutChangingThePage()throws Exception{open(false);ReaderPageView page=(ReaderPageView)a.pageList.getChildAt(0);page.zoom(2);float before=page.tx;drag(a.pageList,500,120,-100,0);assertEquals(0,a.currentPage);assertTrue("zoom pan "+before+" -> "+page.tx+" scale="+page.scale/page.base,page.tx<before-50);}
 @Test public void changingAvailableSpaceRestoresPortraitControls()throws Exception{open(false);layout(360,720);assertFalse("root="+a.root.getWidth()+"x"+a.root.getHeight(),a.chrome.compact);assertEquals(LinearLayout.VERTICAL,a.chrome.dock.getOrientation());assertSame("the page slider sits between the arrows",a.chrome.navigation,a.chrome.seek.getParent());assertEquals(View.VISIBLE,a.chrome.grid.getVisibility());assertNotNull(PageTurnTest.findDescription(a.chrome.grid,"Marcações deste livro"));assertEquals(View.VISIBLE,a.chrome.floating.getVisibility());assertEquals(View.GONE,a.chrome.actions.getVisibility());capture("retrato-novo");int fit=a.pdfFit;PageTurnTest.findDescription(a.chrome.floating,"Ajustar página").performClick();assertEquals((fit+1)%3,a.pdfFit);a.chrome.toggleChrome();layout(360,720);assertEquals(View.VISIBLE,a.chrome.footer.getVisibility());assertEquals("1/3",a.chrome.footPage.getText().toString());assertEquals(View.GONE,a.chrome.floating.getVisibility());capture("ecra-cheio-rodape");a.chrome.toggleChrome();assertEquals(View.GONE,a.chrome.footer.getVisibility());assertEquals(View.VISIBLE,((ViewGroup)a.chrome.toolStrip.getChildAt(5)).getChildAt(1).getVisibility());assertTrue(a.body.getHeight()>400);layout(720,360);assertTrue(a.body.getHeight()>=260);}
 @Test public void narrowLandscapeKeepsToolsScrollableAndPageUsable()throws Exception{open(false);layout(540,280);assertTrue(a.chrome.compact);assertTrue(a.body.getHeight()>=185);assertTrue(a.chrome.toolStrip.getWidth()>a.chrome.actions.getWidth());a.chrome.actions.scrollTo(a.chrome.toolStrip.getWidth(),0);View last=a.chrome.toolStrip.getChildAt(8);assertTrue(last.getRight()-a.chrome.actions.getScrollX()<=a.chrome.actions.getWidth());assertTrue(last.getLeft()-a.chrome.actions.getScrollX()>=0);}
 @Test public void rotationKeepsPdfPageAndZoom()throws Exception{open(false);a.setPage(1);layout(720,360);ReaderPageView page=(ReaderPageView)a.pageList.getChildAt(0);page.zoom(1.8f);page.ty=page.getHeight()/2f-page.imageHeight(page.getDrawable())*page.scale*.5f;page.apply();android.content.res.Configuration portrait=new android.content.res.Configuration(a.getResources().getConfiguration());portrait.orientation=android.content.res.Configuration.ORIENTATION_PORTRAIT;portrait.screenWidthDp=360;portrait.screenHeightDp=720;controller.configurationChange(portrait);a=controller.get();layout(360,720);assertEquals(1,a.currentPage);page=(ReaderPageView)a.pageList.getChildAt(0);assertEquals("stored zoom="+a.getSharedPreferences("seeky",0).getFloat(page.placementKey()+"_zoom",-1)+" size="+page.getWidth()+"x"+page.getHeight(),1.8f,page.scale/page.base,.03f);assertFalse(a.chrome.compact);}
 @Test public void activeSpeechKeepsTransportAndReadingAreaInLandscape()throws Exception{open(false);SpeechEvents.publish(new SpeechEvents.State(a.uri.toString(),"test","A ler em voz alta",0,3,0,true,false));layout(720,360);SpeechTransport transport=(SpeechTransport)a.chrome.speechBar;assertEquals(View.VISIBLE,transport.getVisibility());assertTrue("narration viewport="+a.body.getHeight(),a.body.getHeight()>=220);assertTrue(transport.back.getWidth()>=44);assertEquals(View.VISIBLE,transport.toggle.getVisibility());capture("landscape-tts");}
 @Test public void paletteColoursSpinnerAfterSelectionAndAdapterRefresh()throws Exception{Application app=RuntimeEnvironment.getApplication();ActivityController<Activity> host=Robolectric.buildActivity(Activity.class);Activity activity=host.get();activity.setTheme(android.R.style.Theme_Material_NoActionBar);host.setup();try{for(String theme:new String[]{"Claro","Escuro"}){app.getSharedPreferences("seeky",0).edit().putString("theme",theme).apply();ChoiceSpinner spinner=new ChoiceSpinner(activity);ArrayAdapter<String> adapter=new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{"Grelha","Lista","Todos"});spinner.setAdapter(adapter);LinearLayout group=new LinearLayout(activity);group.addView(spinner,new LinearLayout.LayoutParams(-1,60));activity.setContentView(group);for(int i=0;i<3;i++){spinner.setSelection(i);adapter.notifyDataSetChanged();group.measure(View.MeasureSpec.makeMeasureSpec(320,1073741824),View.MeasureSpec.makeMeasureSpec(100,1073741824));group.layout(0,0,320,100);shadowOf(Looper.getMainLooper()).idle();TextView selected=(TextView)spinner.getSelectedView();assertNotNull(selected);assertEquals(adapter.getItem(i),selected.getText().toString());assertEquals(AppPalette.of(activity).ink,selected.getCurrentTextColor());}spinner.performClick();UiDialog dialog=(UiDialog)ShadowDialog.getLatestDialog();assertTrue(dialog.isShowing());dialog.getListView().performItemClick(dialog.getListView().getChildAt(0),0,0);assertEquals(0,spinner.getSelectedItemPosition());}}finally{host.pause().stop().destroy();}}
}
